python3 - <<'E'
p='src/orchestration/tools/registry.test.ts'
s=open(p).read()
start=s.index("describe('ToolRegistry input validation'")
s=s[:start]+"""const weatherDefinition = {
  name: 'get_weather',
  description: 'Get weather for a location',
  inputSchema: {type: 'object', required: ['location'], properties: {location: {type: 'string'}}},
};

describe('ToolRegistry input validation', () => {
  it('returns a rejection naming location as required and never calls the executor when input is empty', async () => {
    const executor = jest.fn(async () => 'sunny');
    const registry = new ToolRegistry();
    registry.register(weatherDefinition, executor);

    const {result} = await registry.execute(weatherDefinition.name, {});

    expect({calls: executor.mock.calls.length, result}).toEqual({
      calls: 0,
      result: expect.stringMatching(/location.*required|required.*location/i),
    });
  });
});
"""
s="import {jest} from '@jest/globals';\n"+s
open(p,'w').write(s)
E
npx prettier --write src/orchestration/tools/registry.test.ts src/orchestration/tools/registry.ts >/dev/null; cat -n src/orchestration/tools/registry.test.ts | sed -n 1,30p; timeout 300 node --experimental-vm-modules node_modules/jest/bin/jest.js src/orchestration/tools/registry.test.ts 2>&1 | grep -E "Tests:|●"

